H.background();
// Specific heat:  Q = m * c * delta T
// A burner adds heat at a steady rate; the temperature of the sample rises.
const w = H.W, h = H.H;
const m = P.m;        // mass in kg
const c = P.c;        // specific heat in J/(kg*degC)
const power = P.power; // heater power in watts (J/s)
// Heat delivered grows with time, but loops so the bar resets and reheats.
const period = 10;                 // seconds per heating cycle
const tau = (t % period);          // time since this cycle started
const Q = power * tau;             // joules delivered so far
const dT = (m > 1e-9 && c > 1e-9) ? Q / (m * c) : 0;  // temperature rise (degC)
const T = 20 + dT;                 // current temperature, starting at 20 degC
H.text("Specific heat:  Q = m·c·ΔT", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("m = " + m.toFixed(2) + " kg    c = " + c.toFixed(0) + " J/(kg·°C)    P = " + power.toFixed(0) + " W", 24, 52, { color: H.colors.sub, size: 13 });
// Beaker
const bx = 90, bw = 150, bTop = 110, bBot = h - 80;
const bh = bBot - bTop;
H.rect(bx, bTop, bw, bh, { stroke: H.colors.axis, width: 2, radius: 6 });
// fill level fixed; color encodes temperature (cool -> hot)
const heat = H.clamp(dT / 80, 0, 1);
const liqColor = H.hsl(220 - 210 * heat, 78, 52);
const fillTop = bTop + bh * 0.18;
H.rect(bx + 4, fillTop, bw - 8, bBot - fillTop, { fill: liqColor, radius: 4 });
// rising bubbles to show heating (loop within the liquid)
for (let i = 0; i < 6; i++) {
  const phase = (t * (0.6 + i * 0.12) + i * 0.5) % 1;
  const by = bBot - 6 - phase * (bBot - fillTop - 10);
  const bxp = bx + 20 + ((i * 37 + 13) % (bw - 40));
  H.circle(bxp, by, 2.5 + heat * 2, { fill: "rgba(255,255,255,0.5)" });
}
// burner flame under the beaker, flickering with t
const fx = bx + bw / 2;
const flick = 8 * Math.sin(t * 9) + 26;
H.path([[fx - 18, bBot + 8], [fx, bBot + 8 - flick], [fx + 18, bBot + 8]], { color: "none", fill: H.colors.accent2, close: true });
H.path([[fx - 9, bBot + 8], [fx, bBot + 8 - flick * 0.55], [fx + 9, bBot + 8]], { color: "none", fill: H.colors.warn, close: true });
// thermometer bar on the right
const tx = w - 120, tbTop = 110, tbBot = h - 80;
H.rect(tx, tbTop, 26, tbBot - tbTop, { stroke: H.colors.axis, width: 1.5, radius: 13 });
const lvl = H.clamp(dT / 100, 0, 1);
const merc = tbBot - 6 - lvl * (tbBot - tbTop - 12);
H.rect(tx + 5, merc, 16, tbBot - 6 - merc, { fill: H.colors.warn, radius: 8 });
// readouts
H.text("Q = " + (Q / 1000).toFixed(2) + " kJ", w - 160, 52, { color: H.colors.good, size: 14, weight: 700 });
H.text("ΔT = " + dT.toFixed(1) + " °C", w - 160, 74, { color: H.colors.accent, size: 13 });
H.text("T = " + T.toFixed(1) + " °C", tx - 4, tbTop - 12, { color: H.colors.warn, size: 13, weight: 700 });
